from moler.exceptions import ParsingDone

from ta_moler.cmd.egate.generictabcontent import GenericTabContent

__author__ = 'Adrianna Pienkowska'
__copyright__ = 'Copyright (C) 2018, Nokia'
__email__ = 'adrianna.pienkowska@nokia.com'


class SgwDisp(GenericTabContent):
    """Sgwdisp command class."""

    def __init__(self, connection, sgw_id, prompt=None, newline_chars=None, runner=None):
        """
        Sgwdisp command.

        :param connection: moler connection to device, terminal when command is executed.
        :param sgw_id: id of sgw
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(SgwDisp, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.sgw_id = sgw_id
        self._add_list = True
        self._add_dict = True

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "sgw_disp"
        if self.sgw_id:
            cmd = f'{cmd} id={self.sgw_id}'
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_two_rows()
            except ParsingDone:
                pass
        super(SgwDisp, self).on_new_line(line=line, is_full_line=is_full_line)

    def _parse_two_rows(self):
        if 'LIST' in self.current_ret:
            if len(self.current_ret['LIST'][-1]) < 2:
                prev_dict = self.current_ret['LIST'][-2]
                new_value = [prev_dict['Value'], self.current_ret['LIST'][-1]['Value']]
                old_key = self.current_ret['LIST'][-1]['Value']
                self.current_ret['LIST'][-2]['Value'] = new_value
                self.current_ret['DICT'][prev_dict['Parameter']]['Value'] = new_value
                del self.current_ret['DICT'][old_key]
                del self.current_ret['LIST'][-1]
                raise ParsingDone


